#!/bin/bash
# Builds build/Runespeak.app (release, ad-hoc signed).
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
cd "$ROOT"

APP="$ROOT/build/Runespeak.app"
BUNDLE_ID="local.runespeak"
EXECUTABLE="Runespeak"
VERSION="1.0.0"

# Dictionary files (data/*.tsv, generated by tools/build_dictionary.py and committed). The app
# copies them into its data folder at launch; without them it translates with no game names.
DICTIONARY_FILES=(
    official_names.classic.tsv official_names.retail.tsv
    abbreviations.classic.tsv abbreviations.retail.tsv
    chat_commands.classic.tsv chat_commands.retail.tsv
    zone_places.classic.tsv zone_places.retail.tsv
    nicknames.tsv
)
if [ ! -d "$ROOT/data" ]; then
    echo "오류: data/ 폴더가 없습니다. 사전 파일(data/*.tsv)이 있어야 앱을 만들 수 있습니다." >&2
    echo "      공식 이름 표는 tools/build_dictionary.py로 다시 만들 수 있습니다." >&2
    exit 1
fi
missing=0
for name in "${DICTIONARY_FILES[@]}"; do
    if [ ! -s "$ROOT/data/$name" ] || [ -L "$ROOT/data/$name" ]; then
        echo "오류: data/$name 파일이 없거나 비어 있습니다." >&2
        missing=1
    fi
done
[ "$missing" = 0 ] || exit 1

echo "릴리스 빌드 중…"
swift build -c release
BIN_DIR="$(swift build -c release --show-bin-path)"

rm -rf "$APP"
mkdir -p "$APP/Contents/MacOS" "$APP/Contents/Resources"
cp "$BIN_DIR/$EXECUTABLE" "$APP/Contents/MacOS/$EXECUTABLE"
# The linker leaves the debug map of the build in the binary: the path of every source and
# object file, each beginning with the home folder of whoever built it. The app has no use for
# them and is handed to other people (scripts/build-dmg.sh), so they are taken out of the copy.
if ! strip -S "$APP/Contents/MacOS/$EXECUTABLE" 2>/dev/null; then
    echo "실행 파일에서 빌드 경로를 지우지 못했습니다 (strip). 그대로 둡니다."
fi

# SwiftPM resource bundles, if the package ever gains any.
shopt -s nullglob
for bundle in "$BIN_DIR"/*.bundle; do
    cp -R "$bundle" "$APP/Contents/Resources/"
done
shopt -u nullglob

# Dictionary files, checked above.
mkdir -p "$APP/Contents/Resources/data"
bundled=0
shopt -s nullglob
for file in "$ROOT"/data/*.tsv; do
    if [ -f "$file" ] && [ ! -L "$file" ] && [ -s "$file" ]; then
        cp "$file" "$APP/Contents/Resources/data/"
        bundled=$((bundled + 1))
    fi
done
shopt -u nullglob
echo "사전 파일 ${bundled}개를 앱에 넣었습니다."

# App icon: Resources/AppIcon.png (1024 px) when present, else drawn by the app binary itself;
# resized with sips, packed with iconutil.
ICON_KEY=""
ICON_WORK="$(mktemp -d)"
trap 'rm -rf "$ICON_WORK"' EXIT
make_icon_source() {
    if [ -f "$ROOT/Resources/AppIcon.png" ]; then
        cp "$ROOT/Resources/AppIcon.png" "$ICON_WORK/icon.png"
    else
        "$BIN_DIR/$EXECUTABLE" --make-icon "$ICON_WORK/icon.png" >/dev/null 2>&1
    fi
}
if command -v sips >/dev/null 2>&1 && command -v iconutil >/dev/null 2>&1 && make_icon_source; then
    SET="$ICON_WORK/AppIcon.iconset"
    mkdir -p "$SET"
    ok=1
    for size in 16 32 128 256 512; do
        sips -z "$size" "$size" "$ICON_WORK/icon.png" --out "$SET/icon_${size}x${size}.png" >/dev/null 2>&1 || ok=0
        double=$((size * 2))
        sips -z "$double" "$double" "$ICON_WORK/icon.png" --out "$SET/icon_${size}x${size}@2x.png" >/dev/null 2>&1 || ok=0
    done
    if [ "$ok" = 1 ] && iconutil -c icns "$SET" -o "$APP/Contents/Resources/AppIcon.icns" >/dev/null 2>&1; then
        ICON_KEY="    <key>CFBundleIconFile</key>
    <string>AppIcon</string>"
    else
        echo "아이콘을 만들지 못해 기본 아이콘으로 둡니다."
    fi
else
    echo "아이콘 도구가 없어 기본 아이콘으로 둡니다."
fi

cat > "$APP/Contents/Info.plist" <<PLIST
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
    <key>CFBundleDevelopmentRegion</key>
    <string>ko</string>
    <key>CFBundleExecutable</key>
    <string>$EXECUTABLE</string>
    <key>CFBundleIdentifier</key>
    <string>$BUNDLE_ID</string>
    <key>CFBundleInfoDictionaryVersion</key>
    <string>6.0</string>
    <key>CFBundleName</key>
    <string>Runespeak 채팅 번역</string>
    <key>CFBundleDisplayName</key>
    <string>Runespeak 채팅 번역</string>
    <key>CFBundlePackageType</key>
    <string>APPL</string>
    <key>CFBundleShortVersionString</key>
    <string>$VERSION</string>
    <key>CFBundleVersion</key>
    <string>1</string>
$ICON_KEY
    <key>LSMinimumSystemVersion</key>
    <string>14.0</string>
    <key>LSApplicationCategoryType</key>
    <string>public.app-category.utilities</string>
    <key>NSHighResolutionCapable</key>
    <true/>
    <key>NSPrincipalClass</key>
    <string>NSApplication</string>
    <key>NSSupportsAutomaticTermination</key>
    <false/>
    <key>NSScreenCaptureUsageDescription</key>
    <string>채팅창으로 잡아 둔 사각형의 화면 그림에서 글자를 인식하는 데 필요합니다.</string>
    <key>NSHumanReadableCopyright</key>
    <string>팬 제작 도구 · Blizzard Entertainment의 제품이 아닙니다</string>
</dict>
</plist>
PLIST
printf 'APPL????' > "$APP/Contents/PkgInfo"
plutil -lint "$APP/Contents/Info.plist" >/dev/null

# Ad-hoc signature with a fixed identifier, so the screen-recording grant is tied to one name.
codesign --force --sign - --identifier "$BUNDLE_ID" "$APP"
codesign --verify --strict "$APP"

echo "완성: $APP"
